// commentExtractor.js
export class CommentExtractor {
  constructor(content) {
    this.content = content;
  }

  extract() {
    const singleLine = /\/\/(.*)/g;
    const multiLine = /\/\*([\s\S]*?)\*\//g;
    const comments = [];

    let match;
    while ((match = singleLine.exec(this.content))) {
      comments.push({ type: 'single', text: match[1].trim() });
    }
    while ((match = multiLine.exec(this.content))) {
      comments.push({ type: 'multi', text: match[1].trim() });
    }

    return comments;
  }
}
